"use strict";(self.webpackChunk_abdm_docs_site=self.webpackChunk_abdm_docs_site||[]).push([["92511"],{12624(e,t,a){a.r(t),a.d(t,{metadata:()=>n,default:()=>u,frontMatter:()=>c,contentTitle:()=>p,toc:()=>h,assets:()=>d});var n=JSON.parse('{"id":"nhcx/v1/api/onboarding/endpoints/onboarding-validate","title":"Validate participant creation","description":"Confirms a participant creation by presenting the SMS passcode and the transactionId returned by /v2/participant/create.","source":"@site/docs/nhcx/v1/api/onboarding/endpoints/onboarding-validate.mdx","sourceDirName":"nhcx/v1/api/onboarding/endpoints","slug":"/nhcx/v1/api/onboarding/endpoints/onboarding-validate","permalink":"/docs/pr-13/docs/nhcx/v1/api/onboarding/endpoints/onboarding-validate","draft":false,"unlisted":false,"tags":[],"version":"current","lastUpdatedAt":null,"frontMatter":{"title":"Validate participant creation","sidebar_label":"Validate participant creation","sidebar_class_name":"api-method api-method--get","description":"Confirms a participant creation by presenting the SMS passcode and the transactionId returned by /v2/participant/create.","hide_table_of_contents":true,"hide_title":true,"wrapperClassName":"api-doc","source":"nhcx-onboarding.yaml","generated":true},"sidebar":"nhcx-v1-api","previous":{"title":"HEM-entity participant create","permalink":"/docs/pr-13/docs/nhcx/v1/api/onboarding/endpoints/onboarding-v2-participant-hementity-create"},"next":{"title":"Validate participant update","permalink":"/docs/pr-13/docs/nhcx/v1/api/onboarding/endpoints/onboarding-update-validate"}}'),i=a(62540),r=a(43023),o=a(44136),s=JSON.parse('{"id":"onboarding_validate","module":"Onboarding","moduleId":"onboarding","kind":"operation","method":"GET","path":"/validate","server":"https://apisbx.abdm.gov.in/pmjay/sbxhcx/participanthcxservice","servers":[{"url":"https://apisbx.abdm.gov.in/pmjay/sbxhcx/participanthcxservice","description":"Sandbox, Participant service."},{"url":"https://apisprod.nha.gov.in/pmjay/hcx/participanthcxservice","description":"Production."}],"summary":"Validate participant creation","description":"Confirms a participant creation by presenting the SMS passcode and the transactionId returned by /v2/participant/create.\\n\\n### Business purpose\\n\\nRegistering an organisation on a national claims exchange must be authorised by someone who actually controls that organisation\'s registered contact channel. The create call therefore only stages the record and sends a passcode to the mobile number held in HFR or the NHCX payer details; this validation call closes the loop by proving possession of that passcode. It is step 2 of the four-step production onboarding sequence and is what turns a staged participant into a confirmed one.\\n\\n### When to use\\n\\nCall it after /v2/participant/create has returned a transactionid and the passcode has arrived by SMS, and before attempting /v2/participant/update, whose validations require that creation confirmation is already completed. The production URL is https://apisprod.nha.gov.in/pmjay/hcx/participanthcxservice/validate?transactionId=\\"\\"&passcode=\\"\\". The pair is valid for 24 hours. It is one of only three GET operations in the participant service and carries no workflow or x-hcx-status codes.\\n\\n### Preconditions\\n\\n- A completed /v2/participant/create whose response supplied the transactionid.\\n- The passcode delivered to the registered mobile number for that specific transaction; passcodes are bound to a transaction id and cannot be reused across attempts.\\n- Both values presented as query parameters passcode and transactionId within 24 hours of the create call.\\n- A Bearer token in bearer_auth with the Bearer prefix and Accept: application/json, as for every registry call.\\n\\n### Postconditions\\n\\nHTTP 200 with a bare string body; the OpenAPI declares the 200 response type as string and the operation (particiapntValidate) as validating approval from the participant for participant creation. The participant is now confirmed in the registry and satisfies the precondition for /v2/participant/update, which uploads the encryption certificate and callback endpoint. There is no asynchronous callback. A wrong or expired passcode, or an unknown transaction id, returns the registry ErrorResponse envelope on 400 or 404.\\n\\n### Common mistakes\\n\\n- Waiting more than 24 hours; both the transaction id and the passcode expire and the create call must be repeated.\\n- Re-triggering /v2/participant/create while a passcode is pending, which issues a new transaction id and passcode and orphans the earlier pair.\\n- Using a passcode from a different transaction id; passcodes are specific to the transaction that generated them.\\n- Calling /update/validate by mistake; that endpoint confirms updates, not creation.\\n- Losing the transaction id: the documented recovery is to create the request again.\\n\\n### Best practices\\n\\n- Treat the passcode like a one-time credential: never log it, and hand it from the phone holder to the integrator through a controlled channel.\\n- Store transactionid with a 24-hour expiry so the operator dashboard can show whether confirmation is still possible.\\n- Send parameters as query string values on a GET; there is no JSON body.\\n- After success, proceed straight to /v2/participant/update so the certificate and endpoint are in place before any counterparty tries to fetch them.\\n\\n### Related scenario\\n\\nA hospital\'s production onboarding started with /v2/participant/create, which returned transactionid 1vouv8tlz2tnl-1fpspjhwj07c6 and triggered a passcode to the medical superintendent\'s registered phone. The superintendent reads the passcode to the integration engineer, who calls GET /validate?transactionId=1vouv8tlz2tnl-1fpspjhwj07c6&passcode=482913 with the Bearer token. The registry returns 200 and the participant is confirmed. The engineer then calls /v2/participant/update with the Base64 certificate and callback URL, and completes that change with /update/validate.\\n\\n### Specification\\n\\nChapter [Your certificate](/docs/nhcx/v1/getting-started/your-certificate) of the NHCX integration specification.","security":[{"name":"bearerAuth","type":"http","scheme":"bearer","description":"On every NHCX call, the token goes in a header called `bearer_auth`, with the word `Bearer` and a space in front. The sources are not unanimous: the authentication page and the FAQ both write the example as `Authorization`, and the notification endpoint uses `Authorization`. The safe course, and what the adapter does, is to send both headers with the same value."}],"headers":[{"name":"bearer_auth","required":true,"description":"It is `bearer_auth`, not `Authorization`, on NHCX\'s own endpoints.","example":"Bearer <access token>","type":"string"}],"pathParams":[],"queryParams":[{"name":"transactionId","required":true,"description":"","type":"string"},{"name":"passcode","required":true,"description":"","type":"string"}],"body":[],"responses":[{"status":"200","description":"HTTP 200 with a bare string body; the OpenAPI declares the 200 response type as string and the operation (particiapntValidate) as validating approval from the participant for participant creation.","example":{"_contentType":"string","_body":"<confirmation string as declared by the OpenAPI 200 response>"}}],"tag":"Onboarding","tagDescription":"Nothing moves through NHCX until both the sender and the recipient exist in the participant registry, which the platform treats as the source of truth for who may exchange claims data.","curl":"curl --request GET \\\\\\n  --url https://apisbx.abdm.gov.in/pmjay/sbxhcx/participanthcxservice/validate \\\\\\n  --header \'Authorization: Bearer <ACCESS_TOKEN_FROM_SESSIONS_CALL>\' \\\\\\n  --header \'bearer_auth: Bearer <access token>\'","samples":[{"id":"curl","label":"cURL","language":"bash","code":"curl --request GET \\\\\\n  --url https://apisbx.abdm.gov.in/pmjay/sbxhcx/participanthcxservice/validate \\\\\\n  --header \'Authorization: Bearer <ACCESS_TOKEN_FROM_SESSIONS_CALL>\' \\\\\\n  --header \'bearer_auth: Bearer <access token>\'"},{"id":"python","label":"Python","language":"python","code":"import requests\\n\\nresponse = requests.get(\\n    \\"https://apisbx.abdm.gov.in/pmjay/sbxhcx/participanthcxservice/validate\\",\\n    headers={\\n        \\"Authorization\\": \\"Bearer <ACCESS_TOKEN_FROM_SESSIONS_CALL>\\",\\n        \\"bearer_auth\\": \\"Bearer <access token>\\",\\n    },\\n)\\n\\nprint(response.status_code, response.text)"},{"id":"node","label":"Node","language":"javascript","code":"const response = await fetch(\\"https://apisbx.abdm.gov.in/pmjay/sbxhcx/participanthcxservice/validate\\", {\\n  method: \\"GET\\",\\n  headers: {\\n    \\"Authorization\\": \\"Bearer <ACCESS_TOKEN_FROM_SESSIONS_CALL>\\",\\n    \\"bearer_auth\\": \\"Bearer <access token>\\",\\n  },\\n});\\n\\nconsole.log(response.status, await response.text());"}]}');let c={title:"Validate participant creation",sidebar_label:"Validate participant creation",sidebar_class_name:"api-method api-method--get",description:"Confirms a participant creation by presenting the SMS passcode and the transactionId returned by /v2/participant/create.",hide_table_of_contents:!0,hide_title:!0,wrapperClassName:"api-doc",source:"nhcx-onboarding.yaml",generated:!0},p,d={},h=[];function l(e){return(0,i.jsx)(o.A,{operation:s})}function u(e={}){let{wrapper:t}={...(0,r.R)(),...e.components};return t?(0,i.jsx)(t,{...e,children:(0,i.jsx)(l,{...e})}):l(e)}}}]);